  "onl.tp.sonCevap": ["Son cevap: %1", "Reply by: %1", "Responder antes de: %1", "Responder até: %1", "آخر موعد للرد: %1", "Ответить до: %1"],
  "onl.tp.vs.gelen.kabul": ["Cevap vermezsen olağan düzenin gereği kabul edilir.", "If you don't reply, your standing orders accept it.", "Si no respondes, tus órdenes habituales la aceptan.", "Se não responderes, as tuas ordens habituais aceitam.", "إن لم ترد يُقبل وفق نظامك المعتاد.", "Без ответа — принимается по вашему обычному порядку."],
  "onl.tp.vs.gelen.ret": ["Cevap vermezsen olağan düzenin gereği reddedilir.", "If you don't reply, your standing orders decline it.", "Si no respondes, tus órdenes habituales la rechazan.", "Se não responderes, as tuas ordens habituais recusam.", "إن لم ترد يُرفض وفق نظامك المعتاد.", "Без ответа — отклоняется по вашему обычному порядку."],
  "onl.tp.vs.gelen.dustu": ["Cevap vermezsen ay dönünce düşer; kimse cezalanmaz, emanet sahibine döner.", "If you don't reply, it lapses at month's turn; no one is penalised and escrow returns.", "Si no respondes, caduca al cambiar el mes; nadie es penalizado y el depósito vuelve.", "Se não responderes, caduca na viragem do mês; ninguém é penalizado e o depósito volta.", "إن لم ترد يسقط عند تبدّل الشهر؛ بلا عقوبة وتعود الأمانة.", "Без ответа истекает со сменой месяца; никто не наказан, залог возвращается."],
  "onl.tp.vs.giden.kabul": ["Cevap gelmezse alıcının olağan düzeni gereği kabul sayılır.", "If there's no reply, the recipient's standing orders accept it.", "Si no responde, las órdenes habituales del receptor la aceptan.", "Se não houver resposta, as ordens habituais do destinatário aceitam.", "إن لم يأتِ رد يُقبل وفق نظام المتلقي المعتاد.", "Без ответа — принимается по обычному порядку получателя."],
  "onl.tp.vs.giden.ret": ["Cevap gelmezse alıcının düzeni gereği reddedilir; emanetin geri döner.", "If there's no reply, the recipient's orders decline it; your escrow returns.", "Si no responde, las órdenes del receptor la rechazan; tu depósito vuelve.", "Se não houver resposta, as ordens do destinatário recusam; o teu depósito volta.", "إن لم يأتِ رد يُرفض وفق نظام المتلقي وتعود أمانتك.", "Без ответа — отклоняется по порядку получателя; ваш залог вернётся."],
  "onl.tp.vs.giden.dustu": ["Cevap gelmezse ay dönünce düşer; emanetin geri döner.", "If there's no reply, it lapses at month's turn; your escrow returns.", "Si no responde, caduca al cambiar el mes; tu depósito vuelve.", "Se não houver resposta, caduca na viragem do mês; o teu depósito volta.", "إن لم يأتِ رد يسقط عند تبدّل الشهر وتعود أمانتك.", "Без ответа истекает со сменой месяца; ваш залог вернётся."],
