  "onl.tp.gk.s.gecmis": ["Geçmiş", "History", "Historial", "Histórico", "السجل", "История"],
  "onl.tp.gk.dostlukIstek": ["DOSTLUK İSTEKLERİ", "FRIENDSHIP REQUESTS", "SOLICITUDES DE AMISTAD", "PEDIDOS DE AMIZADE", "طلبات الصداقة", "ЗАПРОСЫ ДРУЖБЫ"],
  "onl.tp.gk.dostlukGiden": ["GÖNDERDİĞİN DOSTLUK İSTEKLERİ", "FRIENDSHIP REQUESTS YOU SENT", "SOLICITUDES DE AMISTAD ENVIADAS", "PEDIDOS DE AMIZADE ENVIADOS", "طلبات الصداقة المرسلة", "ОТПРАВЛЕННЫЕ ЗАПРОСЫ ДРУЖБЫ"],
  "onl.tp.gk.istedi": ["Dostluk istedi · %1", "Asked for friendship · %1", "Pidió amistad · %1", "Pediu amizade · %1", "طلب الصداقة · %1", "Просит дружбы · %1"],
  "onl.tp.gk.gonderdin": ["İstek gönderildi · %1", "Request sent · %1", "Solicitud enviada · %1", "Pedido enviado · %1", "أُرسل الطلب · %1", "Запрос отправлен · %1"],
  "onl.tp.gk.teklifler": ["TEKLİFLER", "OFFERS", "OFERTAS", "PROPOSTAS", "العروض", "ПРЕДЛОЖЕНИЯ"],
  "onl.tp.gk.gelenBos": ["Cevap bekleyen teklif yok. Oyuncular ve NPC'ler teklif gönderince burada görünür.", "No offers awaiting reply. Offers from players and NPCs appear here.", "No hay ofertas pendientes. Las de jugadores y PNJ aparecerán aquí.", "Não há propostas pendentes. As de jogadores e PNJ aparecem aqui.", "لا عروض بانتظار الرد. تظهر هنا عروض اللاعبين والشخصيات.", "Нет предложений, ждущих ответа. Здесь появятся предложения игроков и NPC."],
  "onl.tp.gk.gidenBos": ["Açık bir teklifin yok. Bir oyuncunun profilinden teklif verebilirsin.", "You have no open offers. Make one from a player's profile.", "No tienes ofertas abiertas. Haz una desde el perfil de un jugador.", "Não tens propostas abertas. Faz uma no perfil de um jogador.", "ليس لديك عروض مفتوحة. قدّم عرضًا من ملف أحد اللاعبين.", "Открытых предложений нет. Сделайте его в профиле игрока."],
  "onl.tp.gk.anlasmalar": ["SÜREN ANLAŞMALAR", "ONGOING AGREEMENTS", "ACUERDOS EN CURSO", "ACORDOS EM CURSO", "الاتفاقات الجارية", "ДЕЙСТВУЮЩИЕ ДОГОВОРЫ"],
  "onl.tp.gk.surenBos": ["Süren çıraklık, ortaklık ya da borç yok.", "No ongoing apprenticeship, partnership or loan.", "Sin aprendizaje, sociedad ni préstamo en curso.", "Sem aprendizagem, sociedade ou empréstimo em curso.", "لا تلمذة ولا شراكة ولا قرض جارٍ.", "Нет действующего ученичества, товарищества или займа."],
